// agentpager-antigravity v1
// AgentPager (Antigravity) bridge hook runner
// Managed by AgentPager (Antigravity) - do not edit this file manually.
// Forwards Antigravity lifecycle hooks to AgentPager Bridge on 127.0.0.1:49361.

const net = require("node:net");

const HOST = "127.0.0.1";
const PORT = 49361;
const CONNECT_TIMEOUT_MS = 500;

const eventName = process.argv[2] || "Unknown";

// 门禁红线：PreToolUse 属于前置门禁钩子，必须在首帧立即向 stdout 返回 {"decision":"allow"} 显式放行，绝不卡死 agy 循环。
try {
  if (eventName === "PreToolUse") {
    process.stdout.write(JSON.stringify({ decision: "allow" }) + "\n");
  } else {
    process.stdout.write("{}\n");
  }
} catch {
  // 忽略输出异常
}

// 进程全局超时兜底：防止任何不可预期原因阻塞外部进程
const safetyTimer = setTimeout(() => {
  process.exit(0);
}, 1000);
if (safetyTimer.unref) safetyTimer.unref();

let input = "";
process.stdin.setEncoding("utf8");

process.stdin.on("data", chunk => {
  input += chunk;
});

process.stdin.on("end", () => {
  let data = {};
  if (input.trim()) {
    try {
      data = JSON.parse(input);
    } catch {
      data = {};
    }
  }
  forwardToBridge(eventName, data);
});

process.stdin.on("error", () => {
  process.exit(0);
});

function forwardToBridge(event, data) {
  const envelope = {
    hook_source: "antigravity",
    payload: {
      event,
      conversationId: data.conversationId,
      workspacePaths: data.workspacePaths,
      transcriptPath: data.transcriptPath,
      artifactDirectoryPath: data.artifactDirectoryPath,
      modelName: data.modelName,
      toolCall: data.toolCall,
      stepIdx: data.stepIdx,
      invocationNum: data.invocationNum,
      initialNumSteps: data.initialNumSteps,
      executionNum: data.executionNum,
      terminationReason: data.terminationReason,
      error: data.error,
      fullyIdle: data.fullyIdle
    }
  };

  const client = net.createConnection({ host: HOST, port: PORT });
  client.setTimeout(CONNECT_TIMEOUT_MS);

  client.on("connect", () => {
    try {
      client.write(JSON.stringify(envelope) + "\n");
    } catch {
      client.destroy();
      process.exit(0);
    }
  });

  client.on("data", () => {
    client.end();
  });

  client.on("timeout", () => {
    client.destroy();
    process.exit(0);
  });

  client.on("error", () => {
    // Fail-Open：Bridge 未启动时静默退出，绝不阻断 Antigravity
    client.destroy();
    process.exit(0);
  });

  client.on("close", () => {
    process.exit(0);
  });
}
